function preparedDownload(bytes,type,name,label){
 clearDownload();const url=URL.createObjectURL(new Blob([bytes],{type}));downloadUrls.push(url);
 const box=$('qmDownloadReady');box.hidden=false;const copy=document.createElement('span');copy.textContent=label;
 const pdf=type==='application/pdf',checkAccess=e=>{if(!allowed()){e.preventDefault();close(true,pdf?'Sign in again before opening or downloading this PDF.':'Sign in again before downloading.');}};
 const a=document.createElement('a');a.href=url;a.download=name;a.className='qm-download';a.textContent=pdf?'Download PDF':'Download backup';a.addEventListener('click',checkAccess);
 if(pdf){
  a.target='_blank';a.rel='noopener noreferrer';
  const open=document.createElement('a');open.href=url;open.target='_blank';open.rel='noopener noreferrer';open.className='qm-open-pdf';open.textContent='Open PDF in new tab';open.addEventListener('click',checkAccess);
  const actions=document.createElement('div');actions.className='qm-actions';actions.append(open,a);box.append(copy,actions);
 }else box.append(copy,a);
 box.scrollIntoView({block:'nearest',behavior:'smooth'});
}
